function translate(lang, key) {
  const pack = I18N[lang] || I18N.vi;
  return pack[key] || I18N.vi[key] || "";
}

function relativeParts(raw) {
  const then = Date.parse(String(raw).trim().replace(" ", "T"));
  if (Number.isNaN(then)) return null;
  const elapsed = Math.max(0, Date.now() - then) / 1000;
  if (elapsed < 60) return { key: "ago_now", n: 0 };
  if (elapsed < 3600) return { key: "ago_min", n: Math.floor(elapsed / 60) };
  if (elapsed < 86400) return { key: "ago_hour", n: Math.floor(elapsed / 3600) };
  const startToday = new Date();
  startToday.setHours(0, 0, 0, 0);
  const startThen = new Date(then);
  startThen.setHours(0, 0, 0, 0);
  const days = Math.round((startToday - startThen) / 86400000);
  if (days <= 1) return { key: "ago_yesterday", n: 1 };
  if (days < 7) return { key: "ago_day", n: days };
  return null;
}

function applyI18n(lang) {
  document.documentElement.lang = lang === "en" ? "en" : "vi";
  document.querySelectorAll("[data-i18n]").forEach((node) => {
    const text = translate(lang, node.dataset.i18n);
    if (text) node.textContent = text;
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((node) => {
    const text = translate(lang, node.dataset.i18nPlaceholder);
    if (text) node.setAttribute("placeholder", text);
  });
  document.querySelectorAll("[data-count-key]").forEach((node) => {
    const text = translate(lang, node.dataset.countKey);
    if (text) node.textContent = text.replace("{n}", node.dataset.count || "0");
  });
  document.querySelectorAll("[data-time]").forEach((node) => {
    const part = relativeParts(node.dataset.time);
    if (!part) return;
    const text = translate(lang, part.key);
    if (text) node.textContent = text.replace("{n}", String(part.n));
  });
}
